@Test
public void testPruner() {
    SegmentZKMetadata metadata = new OfflineSegmentZKMetadata();
    Map<String, ColumnPartitionMetadata> columnPartitionMap = new HashMap<>();
    int expectedPartition = 3;
    columnPartitionMap.put(PARTITION_COLUMN, new ColumnPartitionMetadata(PARTITION_FUNCTION_NAME, NUM_PARTITION, Collections.singletonList(new IntRange(expectedPartition))));
    SegmentZKMetadataPrunerService prunerService = new SegmentZKMetadataPrunerService(new String[] { PRUNER_NAME });
    SegmentPartitionMetadata segmentPartitionMetadata = new SegmentPartitionMetadata(columnPartitionMap);
    metadata.setPartitionMetadata(segmentPartitionMetadata);
    Pql2Compiler compiler = new Pql2Compiler();
    for (int actualPartition = 0; actualPartition < NUM_PARTITION; actualPartition++) {
        String query = "select count(*) from myTable where " + PARTITION_COLUMN + " = " + actualPartition;
        BrokerRequest brokerRequest = compiler.compileToBrokerRequest(query);
        SegmentPrunerContext prunerContext = new SegmentPrunerContext(brokerRequest);
        Assert.assertEquals(prunerService.prune(metadata, prunerContext), (actualPartition != expectedPartition));
    }
}

@Test
public void testHitCounterWithOneSecondRange() {
    int timeInSec = 1;
    HitCounter hitCounter = new HitCounter(timeInSec);
    for (int i = 0; i < 10; i++) {
        hitCounter.hit(System.currentTimeMillis());
    }
    Assert.assertNotNull(hitCounter);
    Assert.assertEquals(hitCounter.getHitCount(System.currentTimeMillis()), 10);
}

@Test
public void testHitCounterWithFiveSecondRange() {
    int timeInSec = 5;
    HitCounter hitCounter = new HitCounter(timeInSec);
    long currentTimestamp = System.currentTimeMillis();
    for (int i = 0; i < 3; i++) {
        hitCounter.hit(currentTimestamp);
        currentTimestamp += 1L;
    }
    // Sleep for 4 seconds. Same as: Thread.sleep(4000);
    currentTimestamp += 4000L;
    for (int i = 0; i < 7; i++) {
        hitCounter.hit(currentTimestamp);
        currentTimestamp += 1;
    }
    Assert.assertNotNull(hitCounter);
    Assert.assertEquals(hitCounter.getHitCount(currentTimestamp), 10);
}

@Test
public void testHitCounterWithFiveSecondRangeSleepForMoreThanSixSeconds() {
    int timeInSec = 5;
    HitCounter hitCounter = new HitCounter(timeInSec);
    long currentTimestamp = System.currentTimeMillis();
    for (int i = 0; i < 3; i++) {
        hitCounter.hit(currentTimestamp);
        currentTimestamp += 1L;
    }
    // Sleep for more than 6 seconds. Same as: Thread.sleep(6000);
    currentTimestamp += 6000L;
    for (int i = 0; i < 7; i++) {
        hitCounter.hit(currentTimestamp);
        currentTimestamp += 1L;
    }
    Assert.assertNotNull(hitCounter);
    Assert.assertEquals(hitCounter.getHitCount(currentTimestamp), 7);
}

@Test
public void testConcurrency() {
    Random random = new Random();
    // Run the test 3 times
    for (int k = 0; k < 3; k++) {
        long startTime = System.currentTimeMillis();
        int numThreads = 30;
        int numHitsPerThread = 200000;
        int expectedHitCount = numThreads * numHitsPerThread;
        // Randomly set the time range.
        int timeRangeInSecond = random.nextInt(100) + 10;
        HitCounter hitCounter = new HitCounter(timeRangeInSecond);
        List<Thread> threadList = new ArrayList<>();
        for (int i = 0; i < numThreads; i++) {
            Thread thread = new Thread(() -> {
                for (int j = 0; j < numHitsPerThread; j++) {
                    hitCounter.hit(System.currentTimeMillis());
                }
            });
            thread.start();
            threadList.add(thread);
        }
        for (Thread thread : threadList) {
            Uninterruptibles.joinUninterruptibly(thread);
        }
        Assert.assertNotNull(hitCounter);
        Assert.assertEquals(hitCounter.getHitCount(), expectedHitCount);
        long duration = System.currentTimeMillis() - startTime;
        System.out.println(duration);
    }
}

