@Test
public void testRoutingTableServerLoadIsRelativelyEqual() {
    final String tableName = "fakeTable_OFFLINE";
    final int segmentCount = 300;
    final int replicationFactor = 10;
    final int instanceCount = 50;
    // max times we try to satisfy the load criteria. after that we fail the test
    final int maxNumIterations = 5;
    boolean done = false;
    int iterationCount = 1;
    while (!done) {
        ExternalView externalView = createExternalView(tableName, segmentCount, replicationFactor, instanceCount);
        List<InstanceConfig> instanceConfigs = createInstanceConfigs(instanceCount);
        _largeClusterRoutingTableBuilder.computeRoutingTableFromExternalView(tableName, externalView, instanceConfigs);
        List<Map<String, List<String>>> routingTables = _largeClusterRoutingTableBuilder.getRoutingTables();
        Map<String, Integer> segmentCountPerServer = new HashMap<>();
        // Count number of segments assigned per server
        for (Map<String, List<String>> routingTable : routingTables) {
            for (Map.Entry<String, List<String>> entry : routingTable.entrySet()) {
                String serverName = entry.getKey();
                Integer numSegmentsForServer = segmentCountPerServer.get(serverName);
                if (numSegmentsForServer == null) {
                    numSegmentsForServer = 0;
                }
                numSegmentsForServer += entry.getValue().size();
                segmentCountPerServer.put(serverName, numSegmentsForServer);
            }
        }
        int minNumberOfSegmentsAssignedPerServer = Integer.MAX_VALUE;
        int maxNumberOfSegmentsAssignedPerServer = 0;
        for (Integer segmentCountForServer : segmentCountPerServer.values()) {
            if (segmentCountForServer < minNumberOfSegmentsAssignedPerServer) {
                minNumberOfSegmentsAssignedPerServer = segmentCountForServer;
            }
            if (maxNumberOfSegmentsAssignedPerServer < segmentCountForServer) {
                maxNumberOfSegmentsAssignedPerServer = segmentCountForServer;
            }
        }
        if (maxNumberOfSegmentsAssignedPerServer < minNumberOfSegmentsAssignedPerServer * 1.5) {
            done = true;
        } else {
            if (iterationCount++ >= maxNumIterations) {
                Assert.fail("At least one server has more than 150% of the load of the least loaded server, minNumberOfSegmentsAssignedPerServer = " + minNumberOfSegmentsAssignedPerServer + " maxNumberOfSegmentsAssignedPerServer = " + maxNumberOfSegmentsAssignedPerServer);
            }
        }
    }
}

@Test
public void testBrokerSideServerAndSegmentPruning() throws Exception {
    int numIterations = 50;
    for (int iter = 0; iter < numIterations; iter++) {
        NUM_PARTITION = RANDOM.nextInt(8) + 3;
        NUM_REPLICA = RANDOM.nextInt(3) + 3;
        NUM_SERVERS = NUM_REPLICA * (RANDOM.nextInt(10) + 3);
        NUM_SEGMENTS = RANDOM.nextInt(100) + 3;
        // Create the fake property store
        FakePropertyStore fakePropertyStore = new FakePropertyStore();
        // Create the table config, partition mapping,
        TableConfig tableConfig = buildOfflineTableConfig();
        // Create the replica group id to server mapping
        Map<Integer, List<String>> replicaToServerMapping = buildReplicaGroupMapping();
        // Update segment zk metadata.
        Map<Integer, Integer> partitionSegmentCount = new HashMap<>();
        for (int i = 0; i < NUM_PARTITION; i++) {
            partitionSegmentCount.put(i, 0);
        }
        for (int i = 0; i < NUM_SEGMENTS; i++) {
            String segmentName = "segment" + i;
            int partition = i % NUM_PARTITION;
            partitionSegmentCount.put(partition, partitionSegmentCount.get(partition) + 1);
            SegmentZKMetadata metadata = buildOfflineSegmentZKMetadata(segmentName, partition);
            fakePropertyStore.setContents(ZKMetadataProvider.constructPropertyStorePathForSegment(OFFLINE_TABLE_NAME, segmentName), metadata.toZNRecord());
        }
        // Update replica group mapping zk metadata
        updatgeReplicaGroupPartitionAssignment(OFFLINE_TABLE_NAME, fakePropertyStore);
        // Create the fake external view
        ExternalView externalView = buildExternalView(OFFLINE_TABLE_NAME, replicaToServerMapping);
        // Create instance Configs
        List<InstanceConfig> instanceConfigs = new ArrayList<>();
        for (int serverId = 0; serverId < NUM_SERVERS; serverId++) {
            String serverName = "Server_localhost_" + serverId;
            instanceConfigs.add(new InstanceConfig(serverName));
        }
        // Create the partition aware offline routing table builder.
        RoutingTableBuilder routingTableBuilder = buildPartitionAwareOfflineRoutingTableBuilder(fakePropertyStore, tableConfig, externalView, instanceConfigs);
        // Check the query that requires to scan all segment.
        String countStarQuery = "select count(*) from myTable";
        Map<String, List<String>> routingTable = routingTableBuilder.getRoutingTable(buildRoutingTableLookupRequest(countStarQuery));
        // Check that the number of servers picked are always equal or less than the number of servers
        // from a single replica group.
        Assert.assertTrue(routingTable.keySet().size() <= (NUM_SERVERS / NUM_REPLICA));
        // Check that all segments are covered exactly for once.
        Set<String> assignedSegments = new HashSet<>();
        for (List<String> segmentsForServer : routingTable.values()) {
            for (String segmentName : segmentsForServer) {
                Assert.assertFalse(assignedSegments.contains(segmentName));
                assignedSegments.add(segmentName);
            }
        }
        Assert.assertEquals(assignedSegments.size(), NUM_SEGMENTS);
        // Check the broker side server and segment pruning.
        for (int queryPartition = 0; queryPartition < 100; queryPartition++) {
            String filterQuery = "select count(*) from myTable where " + PARTITION_COLUMN + " = " + queryPartition;
            routingTable = routingTableBuilder.getRoutingTable(buildRoutingTableLookupRequest(filterQuery));
            // Check that the number of servers picked are always equal or less than the number of servers
            // in a single replica group.
            Assert.assertTrue(routingTable.keySet().size() <= (NUM_SERVERS / NUM_REPLICA));
            int partition = queryPartition % NUM_PARTITION;
            assignedSegments = new HashSet<>();
            for (List<String> segmentsForServer : routingTable.values()) {
                for (String segmentName : segmentsForServer) {
                    Assert.assertFalse(assignedSegments.contains(segmentName));
                    assignedSegments.add(segmentName);
                }
            }
            Assert.assertEquals(assignedSegments.size(), partitionSegmentCount.get(partition).intValue());
        }
    }
}

