@Test
public void testCreateUpdateSchema() throws JSONException, IOException {
    String schemaName = "testSchema";
    Schema schema = createDummySchema(schemaName);
    String url = _controllerRequestURLBuilder.forSchemaCreate();
    PostMethod postMethod = sendMultipartPostRequest(url, schema.toString());
    Assert.assertEquals(postMethod.getStatusCode(), 200);
    schema.addField(new DimensionFieldSpec("NewColumn", FieldSpec.DataType.STRING, true));
    postMethod = sendMultipartPostRequest(url, schema.toString());
    Assert.assertEquals(postMethod.getStatusCode(), 200);
    String schemaStr = sendGetRequest(_controllerRequestURLBuilder.forSchemaGet(schemaName));
    Schema readSchema = Schema.fromString(schemaStr);
    Schema inputSchema = Schema.fromString(schema.toString());
    Assert.assertEquals(readSchema, inputSchema);
    Assert.assertTrue(readSchema.getFieldSpecMap().containsKey("NewColumn"));
    final String yetAnotherColumn = "YetAnotherColumn";
    Assert.assertFalse(readSchema.getFieldSpecMap().containsKey(yetAnotherColumn));
    schema.addField(new DimensionFieldSpec(yetAnotherColumn, FieldSpec.DataType.STRING, true));
    PutMethod putMethod = sendMultipartPutRequest(_controllerRequestURLBuilder.forSchemaUpdate(schemaName), schema.toString());
    Assert.assertEquals(putMethod.getStatusCode(), 200);
    // verify some more...
    schemaStr = sendGetRequest(_controllerRequestURLBuilder.forSchemaGet(schemaName));
    readSchema = Schema.fromString(schemaStr);
    inputSchema = Schema.fromString(schema.toString());
    Assert.assertEquals(readSchema, inputSchema);
    Assert.assertTrue(readSchema.getFieldSpecMap().containsKey(yetAnotherColumn));
    // error cases
    putMethod = sendMultipartPutRequest(_controllerRequestURLBuilder.forSchemaUpdate(schemaName), schema.toString().substring(1));
    // invalid json
    Assert.assertEquals(putMethod.getStatusCode(), 400);
    schema.setSchemaName("differentSchemaName");
    putMethod = sendMultipartPutRequest(_controllerRequestURLBuilder.forSchemaUpdate(schemaName), schema.toString());
    Assert.assertEquals(putMethod.getStatusCode(), 400);
}

@Test
public void testSegmentCrcApi() throws Exception {
    // Adding table
    TableConfig tableConfig = new TableConfig.Builder(CommonConstants.Helix.TableType.OFFLINE).setTableName(TABLE_NAME).setNumReplicas(1).build();
    _helixResourceManager.addTable(tableConfig);
    // Wait for the table addition
    while (!_helixResourceManager.hasOfflineTable(TABLE_NAME)) {
        Thread.sleep(100);
    }
    // Check when there is no segment.
    Map<String, SegmentMetadata> segmentMetadataTable = new HashMap<>();
    checkCrcRequest(segmentMetadataTable, 0);
    // Upload Segments
    for (int i = 0; i < 5; ++i) {
        SegmentMetadata segmentMetadata = SegmentMetadataMockUtils.mockSegmentMetadata(TABLE_NAME);
        _helixResourceManager.addNewSegment(segmentMetadata, "downloadUrl");
        segmentMetadataTable.put(segmentMetadata.getName(), segmentMetadata);
    }
    // Get crc info from API and check that they are correct.
    checkCrcRequest(segmentMetadataTable, 5);
    // Add more segments
    for (int i = 0; i < 5; ++i) {
        SegmentMetadata segmentMetadata = SegmentMetadataMockUtils.mockSegmentMetadata(TABLE_NAME);
        _helixResourceManager.addNewSegment(segmentMetadata, "downloadUrl");
        segmentMetadataTable.put(segmentMetadata.getName(), segmentMetadata);
    }
    // Get crc info from API and check that they are correct.
    checkCrcRequest(segmentMetadataTable, 10);
    // Delete segments
    _helixResourceManager.deleteSegment(TableNameBuilder.OFFLINE.tableNameWithType(TABLE_NAME), segmentMetadataTable.values().iterator().next().getName());
    // Check crc api
    checkCrcRequest(segmentMetadataTable, 9);
}

@Test
public void testCreateTable() throws Exception {
    // Create an OFFLINE table with an invalid name which should fail
    // NOTE: Set bad table name inside table config builder is not allowed, so have to explicitly set in table config
    TableConfig offlineTableConfig = _offlineBuilder.build();
    offlineTableConfig.setTableName("bad__table__name");
    try {
        sendPostRequest(_createTableUrl, offlineTableConfig.toJSONConfigString());
        Assert.fail("Creation of an OFFLINE table with two underscores in the table name does not fail");
    } catch (IOException e) {
        // Expected 400 Bad Request
        Assert.assertTrue(e.getMessage().startsWith("Server returned HTTP response code: 400"));
    }
    // Create an OFFLINE table with a valid name which should succeed
    offlineTableConfig.setTableName("valid_table_name");
    String offlineTableJSONConfigString = offlineTableConfig.toJSONConfigString();
    sendPostRequest(_createTableUrl, offlineTableJSONConfigString);
    // Create an OFFLINE table that already exists which should fail
    try {
        sendPostRequest(_createTableUrl, offlineTableJSONConfigString);
        Assert.fail("Creation of an existing OFFLINE table does not fail");
    } catch (IOException e) {
        // Expected 409 Conflict
        Assert.assertTrue(e.getMessage().startsWith("Server returned HTTP response code: 409"));
    }
    // Create an OFFLINE table with invalid replication config
    offlineTableConfig.getValidationConfig().setReplication("abc");
    offlineTableConfig.setTableName("invalid_replication_table");
    try {
        sendPostRequest(_createTableUrl, offlineTableConfig.toJSONConfigString());
        Assert.fail("Creation of an invalid OFFLINE table does not fail");
    } catch (IOException e) {
        // Expected 400 Bad Request
        Assert.assertTrue(e.getMessage().startsWith("Server returned HTTP response code: 400"));
    }
    // Create a REALTIME table with an invalid name which should fail
    // NOTE: Set bad table name inside table config builder is not allowed, so have to explicitly set in table config
    TableConfig realtimeTableConfig = _realtimeBuilder.build();
    realtimeTableConfig.setTableName("bad__table__name");
    try {
        sendPostRequest(_createTableUrl, realtimeTableConfig.toJSONConfigString());
        Assert.fail("Creation of a REALTIME table with two underscores in the table name does not fail");
    } catch (IOException e) {
        // Expected 400 Bad Request
        Assert.assertTrue(e.getMessage().startsWith("Server returned HTTP response code: 400"));
    }
    // Creating a REALTIME table without a valid schema should fail
    _realtimeBuilder.setSchemaName("invalidSchemaName");
    TableConfig invalidConfig = _realtimeBuilder.build();
    try {
        sendPostRequest(_createTableUrl, realtimeTableConfig.toJSONConfigString());
        Assert.fail("Creation of a REALTIME table without a valid schema does not fail");
    } catch (IOException e) {
        // Expected 400 Bad Request
        Assert.assertTrue(e.getMessage().startsWith("Server returned HTTP response code: 400"));
    }
    // Creating a REALTIME table with a different schema name in the config should succeed (backwards compatibility mode)
    String schemaName = "differentRTSchema";
    _realtimeBuilder.setSchemaName(schemaName);
    // use a different table name so it doesn't associate a previously uploaded schema with the table
    _realtimeBuilder.setTableName("RT_TABLE");
    addDummySchema(schemaName);
    TableConfig diffConfig = _realtimeBuilder.build();
    sendPostRequest(_createTableUrl, diffConfig.toJSONConfigString());
    // Create a REALTIME table with a valid name and schema which should succeed
    _realtimeBuilder.setTableName(REALTIME_TABLE_NAME);
    _realtimeBuilder.setSchemaName(REALTIME_TABLE_NAME);
    TableConfig config = _realtimeBuilder.build();
    String realtimeTableJSONConfigString = config.toJSONConfigString();
    sendPostRequest(_createTableUrl, realtimeTableJSONConfigString);
    // TODO: check whether we should allow POST request to create REALTIME table that already exists
    // Create a REALTIME table that already exists which should succeed
    sendPostRequest(_createTableUrl, realtimeTableJSONConfigString);
}

