    instances = getInstanceList(8);
    when(mockHelixAdmin.getInstancesInClusterWithTag(anyString(), anyString())).thenReturn(instances);
    when(mockHelixAdmin.getInstancesInCluster(anyString())).thenReturn(instances);
    rebalancedIdealState = testRebalance(rebalancedIdealState, tableConfig, rebalanceUserConfig, targetNumReplicas, nSegments, instances, true);
    // replace servers
    String removedServer = instances.remove(0);
    instances.add(removedServer + "_replaced_server");
    when(mockHelixAdmin.getInstancesInClusterWithTag(anyString(), anyString())).thenReturn(instances);
    when(mockHelixAdmin.getInstancesInCluster(anyString())).thenReturn(instances);
    rebalancedIdealState = testRebalance(rebalancedIdealState, tableConfig, rebalanceUserConfig, targetNumReplicas, nSegments, instances, true);
    // reduce targetNumReplicas
    targetNumReplicas = 1;
    tableConfig = new TableConfig.Builder(CommonConstants.Helix.TableType.OFFLINE).setTableName(offlineTableName).setNumReplicas(targetNumReplicas).build();
    rebalancedIdealState = testRebalance(rebalancedIdealState, tableConfig, rebalanceUserConfig, targetNumReplicas, nSegments, instances, true);
