@Test
public void testWithinQuota() throws IOException, InvalidConfigException {
    File tempFile = new File(TEST_DIR, "small_file");
    tempFile.createNewFile();
    byte[] data = new byte[1024];
    Arrays.fill(data, (byte) 1);
    try (FileOutputStream ostr = new FileOutputStream(tempFile)) {
        ostr.write(data);
    }
    String tableName = "testTable";
    setupTableSegmentSize(4800L, 900L, 0);
    when(_tableConfig.getTableName()).thenReturn(tableName);
    when(_tableConfig.getQuotaConfig()).thenReturn(_quotaConfig);
    when(_quotaConfig.storageSizeBytes()).thenReturn(3000L);
    when(_quotaConfig.getStorage()).thenReturn("3K");
    StorageQuotaChecker checker = new StorageQuotaChecker(_tableConfig, _tableSizeReader, _controllerMetrics, _pinotHelixResourceManager);
    StorageQuotaChecker.QuotaCheckerResponse response = checker.isSegmentStorageWithinQuota(TEST_DIR, tableName, "segment1", 1000);
    Assert.assertTrue(response.isSegmentWithinQuota);
    Assert.assertEquals(_controllerMetrics.getValueOfTableGauge(tableName, ControllerGauge.TABLE_STORAGE_QUOTA_UTILIZATION), 80L);
    // Quota exceeded.
    when(_quotaConfig.storageSizeBytes()).thenReturn(2800L);
    when(_quotaConfig.getStorage()).thenReturn("2.8K");
    response = checker.isSegmentStorageWithinQuota(TEST_DIR, tableName, "segment1", 1000);
    Assert.assertFalse(response.isSegmentWithinQuota);
    Assert.assertEquals(_controllerMetrics.getValueOfTableGauge(tableName, ControllerGauge.TABLE_STORAGE_QUOTA_UTILIZATION), 85L);
    // Table already over quota.
    setupTableSegmentSize(6000L, 900L, 0);
    when(_quotaConfig.storageSizeBytes()).thenReturn(2800L);
    when(_quotaConfig.getStorage()).thenReturn("2.8K");
    response = checker.isSegmentStorageWithinQuota(TEST_DIR, tableName, "segment1", 1000);
    Assert.assertFalse(response.isSegmentWithinQuota);
    Assert.assertEquals(_controllerMetrics.getValueOfTableGauge(tableName, ControllerGauge.TABLE_STORAGE_QUOTA_UTILIZATION), 107L);
    // no response from any server
    setupTableSegmentSize(-1, -1, 0);
    when(_quotaConfig.storageSizeBytes()).thenReturn(2800L);
    when(_quotaConfig.getStorage()).thenReturn("2.8K");
    response = checker.isSegmentStorageWithinQuota(TEST_DIR, tableName, "segment1", 1000);
    Assert.assertTrue(response.isSegmentWithinQuota);
    // partial response from servers, but table already over quota
    setupTableSegmentSize(6000L, 900L, -2);
    when(_quotaConfig.storageSizeBytes()).thenReturn(2800L);
    when(_quotaConfig.getStorage()).thenReturn("2.8K");
    response = checker.isSegmentStorageWithinQuota(TEST_DIR, tableName, "segment1", 1000);
    Assert.assertFalse(response.isSegmentWithinQuota);
    // partial response from servers, but current estimate within quota
    setupTableSegmentSize(2000L, 900L, -2);
    when(_quotaConfig.storageSizeBytes()).thenReturn(2800L);
    when(_quotaConfig.getStorage()).thenReturn("2.8K");
    response = checker.isSegmentStorageWithinQuota(TEST_DIR, tableName, "segment1", 1000);
    Assert.assertTrue(response.isSegmentWithinQuota);
}

@Test
public void testRebuildBrokerResourceWhenBrokerAdded() throws Exception {
    // Check that the first table we added doesn't need to be rebuilt(case where ideal state brokers and brokers in broker resource are the same.
    String partitionName = _offlineTableConfig.getTableName();
    HelixAdmin helixAdmin = _helixManager.getClusterManagmentTool();
    IdealState idealState = HelixHelper.getBrokerIdealStates(helixAdmin, HELIX_CLUSTER_NAME);
    // Ensure that the broker resource is not rebuilt.
    Assert.assertTrue(idealState.getInstanceSet(partitionName).equals(_pinotHelixResourceManager.getAllInstancesForBrokerTenant(TagNameUtils.DEFAULT_TENANT_NAME)));
    _pinotHelixResourceManager.rebuildBrokerResourceFromHelixTags(partitionName);
    // Add another table that needs to be rebuilt
    TableConfig offlineTableConfigTwo = new TableConfig.Builder(CommonConstants.Helix.TableType.OFFLINE).setTableName(TEST_TABLE_TWO).build();
    _pinotHelixResourceManager.addTable(offlineTableConfigTwo);
    String partitionNameTwo = offlineTableConfigTwo.getTableName();
    // Add a new broker manually such that the ideal state is not updated and ensure that rebuild broker resource is called
    final String brokerId = "Broker_localhost_2";
    InstanceConfig instanceConfig = new InstanceConfig(brokerId);
    instanceConfig.setInstanceEnabled(true);
    instanceConfig.setHostName("Broker_localhost");
    instanceConfig.setPort("2");
    helixAdmin.addInstance(HELIX_CLUSTER_NAME, instanceConfig);
    helixAdmin.addInstanceTag(HELIX_CLUSTER_NAME, instanceConfig.getInstanceName(), TagNameUtils.getBrokerTagForTenant(TagNameUtils.DEFAULT_TENANT_NAME));
    idealState = HelixHelper.getBrokerIdealStates(helixAdmin, HELIX_CLUSTER_NAME);
    // Assert that the two don't equal before the call to rebuild the broker resource.
    Assert.assertTrue(!idealState.getInstanceSet(partitionNameTwo).equals(_pinotHelixResourceManager.getAllInstancesForBrokerTenant(TagNameUtils.DEFAULT_TENANT_NAME)));
    _pinotHelixResourceManager.rebuildBrokerResourceFromHelixTags(partitionNameTwo);
    idealState = HelixHelper.getBrokerIdealStates(helixAdmin, HELIX_CLUSTER_NAME);
    // Assert that the two do equal after being rebuilt.
    Assert.assertTrue(idealState.getInstanceSet(partitionNameTwo).equals(_pinotHelixResourceManager.getAllInstancesForBrokerTenant(TagNameUtils.DEFAULT_TENANT_NAME)));
}

@Test
public void testPushTimePersistence() throws Exception {
    SegmentMetadata segmentMetadata = SegmentMetadataMockUtils.mockSegmentMetadata(TEST_TABLE_NAME, TEST_SEGMENT_NAME);
    _pinotHelixResourceManager.addNewSegment(segmentMetadata, "http://dummy/");
    OfflineSegmentZKMetadata offlineSegmentZKMetadata = _pinotHelixResourceManager.getOfflineSegmentZKMetadata(TEST_TABLE_NAME, TEST_SEGMENT_NAME);
    long pushTime = offlineSegmentZKMetadata.getPushTime();
    // Check that the segment has been pushed in the last 30 seconds
    Assert.assertTrue(System.currentTimeMillis() - pushTime < 30_000);
    // Check that there is no refresh time
    Assert.assertEquals(offlineSegmentZKMetadata.getRefreshTime(), Long.MIN_VALUE);
    // Refresh the segment
    Mockito.when(segmentMetadata.getCrc()).thenReturn(Long.toString(System.nanoTime()));
    _pinotHelixResourceManager.refreshSegment(segmentMetadata, offlineSegmentZKMetadata, "http://dummy/");
    offlineSegmentZKMetadata = _pinotHelixResourceManager.getOfflineSegmentZKMetadata(TEST_TABLE_NAME, TEST_SEGMENT_NAME);
    // Check that the segment still has the same push time
    Assert.assertEquals(offlineSegmentZKMetadata.getPushTime(), pushTime);
    // Check that the refresh time is in the last 30 seconds
    Assert.assertTrue(System.currentTimeMillis() - offlineSegmentZKMetadata.getRefreshTime() < 30_000L);
}

